import{_ as n,a0 as p,w as u,s as l,ao as r,I as o,a1 as s,A as i,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"如何在 Ubuntu 上用 Go For It 管理您的待辦清單 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上用 Go For It 管理您的待辦清單 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上用 Go For It 管理您的待辦清單 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上用 Go For It 管理您的待辦清單 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151105 How to Manage Your To-Do Lists in Ubuntu Using Go For It Application","title":"如何在 Ubuntu 上用 Go For It 管理您的待辦清單","tag":"201511","desc":""},"relativePath":"201511/20151105 How to Manage Your To-Do Lists in Ubuntu Using Go For It Application.md","filePath":"[post].md"}'),m={name:"201511/20151105 How to Manage Your To-Do Lists in Ubuntu Using Go For It Application.md"};function d(f,t,g,w,b,T){const a=p("Link");return u(),l("div",null,[t[18]||(t[18]=r('<h1 id="如何在-ubuntu-上用-go-for-it-管理您的待辦清單" tabindex="-1">如何在 Ubuntu 上用 Go For It 管理您的待辦清單 <a class="header-anchor" href="#如何在-ubuntu-上用-go-for-it-管理您的待辦清單" aria-label="Permalink to “如何在 Ubuntu 上用 Go For It 管理您的待辦清單”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-featured1.jpg" alt=""></p><p>任務管理可以説是工作及日常生活中最重要也最具挑戰性的事情之一。當您在工作中承擔越來越多的責任時，您的表現將與您管理任務的能力直接掛鈎。</p><p>若您的工作有部分需要在電腦上完成，那麼您一定很樂意知道，有多款應用軟件自稱可以為您減輕任務管理的負擔。即便這些軟件中的大多數都是為 Windows 用户服務的，在 Linux 系統中仍然有不少選擇。在本文中，我們就來討論這樣一款軟件：Go For It.</p><h3 id="go-for-it" tabindex="-1">Go For It <a class="header-anchor" href="#go-for-it" aria-label="Permalink to “Go For It”">​</a></h3>',5)),o("p",null,[s(a,{href:"http://manuel-kehl.de/projects/go-for-it/"},{default:i(()=>[...t[0]||(t[0]=[e("Go For It",-1)])]),_:1}),t[1]||(t[1]=e(" (GFI) 由 Manuel Kehl 開發，他聲稱：“這是款簡單易用且時尚優雅的生產力軟件，以待辦清單（To-Do List）為主打特色，並整合了一個能讓你專注於當前事務的定時器。”這款軟件的定時器功能尤其有趣，它還可以讓您在繼續工作之前暫停下來，放鬆一段時間。",-1))]),t[19]||(t[19]=r(`<h3 id="下載並安裝" tabindex="-1">下載並安裝 <a class="header-anchor" href="#下載並安裝" aria-label="Permalink to “下載並安裝”">​</a></h3><p>使用基於 Debian 系統（如Ubuntu）的用户可以通過運行以下終端命令輕鬆地安裝這款軟件：</p><pre><code>sudo add-apt-repository ppa:mank319/go-for-it
sudo apt-get update
sudo apt-get install go-for-it
</code></pre><p>以上命令執行完畢後，您就可以使用這條命令運行這款應用軟件了：</p><pre><code>go-for-it
</code></pre><h3 id="使用及配置" tabindex="-1">使用及配置### <a class="header-anchor" href="#使用及配置" aria-label="Permalink to “使用及配置###”">​</a></h3><p>當你第一次運行 GFI 時，它的界面是長這樣的：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-first-run1.png" alt="gfi-first-run"></p><p>可以看到，界面由三個標籤頁組成，分別是<em>待辦</em> (To-Do)，<em>定時器</em> (Timer)和<em>完成</em> (Done)。<em>待辦</em>頁是一個任務列表（上圖所示的4個任務是默認生成的——您可以點擊頭部的方框刪除它們），<em>定時器</em>頁內含有任務定時器，而<em>完成</em>頁則是已完成任務的列表。底部有個文本框，您可以在此輸入任務描述，並點擊“+”號將任務添加到上面的列表中。</p><p>舉個例子，我將一個名為“MTE-research-work”的任務添加到了列表中，並點擊選中了它，如下圖所示：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-task-added1.png" alt="gfi-task-added"></p><p>然後我進入<em>定時器</em>頁，在這裏我可以看到一個為當前“MTE-reaserch-work”任務設定的定時器，定時25分鐘。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-active-task-timer.png" alt="gfi-active-task-timer"></p><p>當然，您可以將定時器設定為你喜歡的任何值。然而我並沒有修改，而是直接點擊下方的“開始 (Start)”按鈕啓動定時器。一旦剩餘時間為60秒，GFI 就會給出一個提示。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-first-notification-new.jpg" alt="gfi-first-notification-new"></p><p>一旦時間到，它會提醒我休息5分鐘。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-time-up-notification-new.jpg" alt="gfi-time-up-notification-new"></p><p>5分鐘過後，我可以為我的任務再次開啓定時器。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-break-time-up-new.jpg" alt="gfi-break-time-up-new"></p><p>任務完成以後，您可以點擊<em>定時器</em>頁中的“完成 (Done)”按鈕，然後這個任務就會從<em>待辦</em>頁被轉移到<em>完成</em>頁。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-task-done1.png" alt="gfi-task-done"></p><p>GFI 也能讓您稍微調整一些它的設置。例如，下圖所示的設置窗口就包含了一些選項，讓您修改默認的任務時長，休息時長和提示時刻。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/gfi-settings1.png" alt="gfi-settings"></p>`,23)),o("p",null,[t[3]||(t[3]=e("值得一提的是，GFI 是以 TODO.txt 格式保存待辦清單的，這種格式方便了移動設備之間的同步，也讓您能使用其他前端程序來編輯任務——更多詳情請閲讀",-1)),s(a,{href:"http://todotxt.com/"},{default:i(()=>[...t[2]||(t[2]=[e("這裏",-1)])]),_:1}),t[4]||(t[4]=e("。",-1))]),t[20]||(t[20]=o("p",null,"您還可以通過以下視頻觀看 GFI 的動態展示。",-1)),t[21]||(t[21]=o("p",null,"注：youtube 視頻",-1)),t[22]||(t[22]=o("iframe",{frameborder:"0",src:"http://www.youtube.com/embed/mnw556C9FZQ?autoplay=1&autohide=2&border=1&wmode=opaque&enablejsapi=1&controls=1&showinfo=0",id:"youtube-iframe"},null,-1)),t[23]||(t[23]=o("h3",{id:"結論",tabindex:"-1"},[e("結論### "),o("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論###”"},"​")],-1)),t[24]||(t[24]=o("p",null,"正如您所看到的，GFI 是一款簡潔明瞭且易於使用的任務管理軟件。雖然它沒有提供非常豐富的功能，但它實現了它的承諾，定時器的整合特別有用。如果您正在尋找一款實現了基礎功能，並且開源的 Linux 任務管理軟件，Go For It 值得您一試。",-1)),t[25]||(t[25]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),s(a,{href:"https://www.maketecheasier.com/to-do-lists-ubuntu-go-for-it/"},{default:i(()=>[...t[5]||(t[5]=[e("https://www.maketecheasier.com/to-do-lists-ubuntu-go-for-it/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),s(a,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:i(()=>[...t[7]||(t[7]=[e("Himanshu Arora",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),s(a,{href:"https://github.com/Ricky-Gong"},{default:i(()=>[...t[8]||(t[8]=[e("Ricky-Gong",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),s(a,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[9]||(t[9]=[e("Caroline",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),s(a,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const G=n(m,[["render",d]]);export{I as __pageData,G as default};
